package scalahdl.emit

import java.nio.charset.StandardCharsets
import scalahdl.elab.{Module, param}

private class HeaderGenerator(width: Int, pipelined: Boolean)
    extends Module(param("w", width), param("pipelined", pipelined))

class EmissionHeaderSuite extends munit.FunSuite:

  private val expectedHeader =
    "// Generated by ScalaHDL 0.1.0-SNAPSHOT\n" +
    "// Generator: scalahdl.emit.HeaderGenerator\n" +
    "// Parameters: w8, pipelined\n"

  test("default emission header uses build version and captured top provenance"):
    val design = (new HeaderGenerator(8, pipelined = true)).elaborateDesign()
    val emitted = new Emission().emit(design)

    assertEquals(design.generation.generatorClass, "scalahdl.emit.HeaderGenerator")
    assertEquals(design.generation.parameters, List("w8", "pipelined"))
    assert(emitted.files.head._2.startsWith(expectedHeader), emitted.files.head._2)

  test("identical inputs produce byte-for-byte identical headers and files"):
    val design = (new HeaderGenerator(8, pipelined = true)).elaborateDesign()
    val first = new Emission().emit(design)
    val second = new Emission().emit(design)

    val firstBytes = first.files.map { case (name, content) =>
      name -> content.getBytes(StandardCharsets.UTF_8).toList
    }
    val secondBytes = second.files.map { case (name, content) =>
      name -> content.getBytes(StandardCharsets.UTF_8).toList
    }
    assertEquals(firstBytes, secondBytes)
    assertEquals(first, second)

  test("false Boolean parameters use the canonical empty-name representation"):
    val emitted = new Emission().emit(
      (new HeaderGenerator(8, pipelined = false)).elaborateDesign())

    assert(emitted.files.head._2.contains("// Parameters: w8\n"),
      emitted.files.head._2)
